import { Suspense } from 'react';
import { SlowAnalyticsGraph, FastSidebar } from './components';

export default function Dashboard() {
  return (
    <div className="flex">
      {/* This renders instantly */}
      <FastSidebar />

      <main>
        <h1>Dashboard</h1>
        {/* 
          STREAMING MAGIC! 
          The server sends the <h1> and the <p>Loading...</p> instantly.
          It keeps the connection open, and streams the <SlowAnalyticsGraph> 
          HTML down the pipe whenever it finishes calculating!
        */}
        <Suspense fallback={<p>Loading heavy graph...</p>}>
          <SlowAnalyticsGraph />
        </Suspense>
      </main>
    </div>
  );
}
